import { Injectable } from '@angular/core';

@Injectable({ providedIn: 'root' })
export class ChatbotSessionService {
  private readonly SESSION_KEY = 'chatbot_sesion_id';

  obtenerSesionId(): string {
    let sesionId = sessionStorage.getItem(this.SESSION_KEY);
    if (!sesionId) {
      sesionId = this.generarSesionId();
      sessionStorage.setItem(this.SESSION_KEY, sesionId);
    }
    return sesionId;
  }

  private generarSesionId(): string {
    return `chat_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`;
  }

  limpiarSesion(): void {
    sessionStorage.removeItem(this.SESSION_KEY);
  }
}
