import { Injectable } from '@angular/core';
import { MensajeChatVisual } from '../interfaces/chatbot.interface';

@Injectable({ providedIn: 'root' })
export class ChatbotStorageService {
  private readonly STORAGE_PREFIX = 'chatbot_';

  guardarMensajes(sesionId: string, mensajes: MensajeChatVisual[]): void {
    // Convertir Date a string para almacenar
    const mensajesParaGuardar = mensajes.slice(-50).map(msg => ({
      ...msg,
      timestamp: msg.timestamp.toISOString()
    }));
    localStorage.setItem(
      `${this.STORAGE_PREFIX}${sesionId}`,
      JSON.stringify(mensajesParaGuardar)
    );
  }

  cargarMensajes(sesionId: string): MensajeChatVisual[] | null {
    const data = localStorage.getItem(`${this.STORAGE_PREFIX}${sesionId}`);
    if (data) {
      const parsed = JSON.parse(data);
      // Convertir string de vuelta a Date
      return parsed.map((msg: any) => ({
        ...msg,
        timestamp: new Date(msg.timestamp)
      }));
    }
    return null;
  }

  limpiarMensajes(sesionId: string): void {
    localStorage.removeItem(`${this.STORAGE_PREFIX}${sesionId}`);
  }
}
