import { MensajeChatVisual } from '../../../../../core/interfaces/chatbot.interface';

export interface IMessageProcessor {
  procesarMensaje(mensaje: MensajeChatVisual): MensajeChatVisual;
  puedeProcesar(mensaje: MensajeChatVisual): boolean;
}

// Estrategia para mensajes de usuario
export class UserMessageProcessor implements IMessageProcessor {
  procesarMensaje(mensaje: MensajeChatVisual): MensajeChatVisual {
    return {
      ...mensaje,
      text: this.sanitizarTexto(mensaje.text)
    };
  }

  puedeProcesar(mensaje: MensajeChatVisual): boolean {
    return mensaje.sender === 'user';
  }

  private sanitizarTexto(text: string): string {
    const map: Record<string, string> = {
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#39;'
    };
    return text.replace(/[&<>"']/g, m => map[m]);
  }
}

// Estrategia para mensajes del asistente
export class AssistantMessageProcessor implements IMessageProcessor {
  procesarMensaje(mensaje: MensajeChatVisual): MensajeChatVisual {
    return {
      ...mensaje,
      text: mensaje.text
    };
  }

  puedeProcesar(mensaje: MensajeChatVisual): boolean {
    return mensaje.sender === 'robot';
  }

  private formatearRespuesta(texto: string): string {
    if (texto.includes('código maestro') || texto.includes('codigo maestro')) {
      texto = '🔐 ' + texto;
    }
    if (texto.includes('error') || texto.includes('problema')) {
      texto = '⚠️ ' + texto;
    }
    if (texto.includes('éxito') || texto.includes('correctamente')) {
      texto = '✅ ' + texto;
    }
    if (texto.includes('bienvenido') || texto.includes('hola')) {
      texto = '🤖 ' + texto;
    }
    return texto;
  }
}

// Estrategia para mensajes de sistema
export class SystemMessageProcessor implements IMessageProcessor {
  procesarMensaje(mensaje: MensajeChatVisual): MensajeChatVisual {
    return {
      ...mensaje,
      text: `<span class="sigpaz-system-message">ℹ️ ${mensaje.text}</span>`
    };
  }

  puedeProcesar(mensaje: MensajeChatVisual): boolean {
    return mensaje.sender === 'system' as any;
  }
}
