import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, of } from 'rxjs';
import { catchError, map } from 'rxjs/operators';
import { MensajeChatVisual, ChatbotResponse } from '../interfaces/chatbot.interface';
import { environment } from '../../../environments/environment';

@Injectable({ providedIn: 'root' })
export class ChatbotService {
  private readonly API_URL = environment.apiUrl + '/chatbot';

  constructor(private http: HttpClient) {}

  obtenerHistorial(sesionId: string): Observable<MensajeChatVisual[]> {
    return this.http.get<{ success: boolean; data: any[] }>(
      `${this.API_URL}/historial?sesion_id=${sesionId}`
    ).pipe(
      map(resp => {
        if (resp.data && resp.data.length > 0) {
          return resp.data.map((msg: any): MensajeChatVisual => {
            // Determinar el sender de forma segura
            let sender: 'user' | 'robot' = 'robot';
            if (msg.remitente === 'usuario') {
              sender = 'user';
            } else if (msg.remitente === 'asistente' || msg.remitente === 'robot') {
              sender = 'robot';
            }

            return {
              id: msg.id,
              sender: sender,
              text: msg.contenido,
              timestamp: new Date(msg.fechaCompleta || msg.fecha)
            };
          });
        }
        return [];
      }),
      catchError(() => of([]))
    );
  }

  calificar(mensajeId: number, puntuacion: number, fueUtil: boolean): Observable<any> {
    return this.http.post(`${this.API_URL}/calificar`, {
      mensaje_id: mensajeId,
      puntuacion,
      fue_util: fueUtil
    });
  }

  limpiarHistorial(sesionId: string): Observable<any> {
    return this.http.delete(`${this.API_URL}/historial?sesion_id=${sesionId}`);
  }

  enviarMensaje(mensaje: string, sesionId: string): Observable<ChatbotResponse> {
  return this.http.post<ChatbotResponse>(`${this.API_URL}/mensaje`, {
    mensaje,
    sesion_id: sesionId
  }).pipe(
    map(resp => {
      if (resp.data && resp.data.respuesta) {
        // Agregar flag para indicar que el texto tiene formato
        resp.data.html = this.textoAHTML(resp.data.respuesta);
      }
      return resp;
    }),
    catchError(error => {
      console.error('Error al enviar mensaje:', error);
      return of({
        success: false,
        data: {
          respuesta: 'Lo siento, ocurrió un error. Por favor, intenta de nuevo.',
          fuente: 'error'
        }
      });
    })
  );
}

private textoAHTML(texto: string): string {
  let html = texto.replace(/\n/g, '<br>');
  html = html.replace(/(\d+)\.\s+([^\n]+)/g, '<li>$2</li>');
  html = html.replace(/<li>(.*?)<\/li>/g, '<ol><li>$1</li></ol>');
  html = html.replace(/-\s+([^\n]+)/g, '<li>$1</li>');
  html = html.replace(/<li>(.*?)<\/li>/g, '<ul><li>$1</li></ul>');
  html = html.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  return html;
}
}
